{
  "implementation": "def solve(case):
    # Extract data
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Build edges list with mutual reachability weights
    edges = []
    for a, b, d in distances:
        node1, node2 = (a, b) if a <= b else (b, a)
        weight = max(core[node1], core[node2], d)
        edges.append((weight, node1, node2))

    # Sort deterministically: weight, then node1, then node2
    edges.sort()

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; cannot form MST")

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
